'use client';
import { useEffect, useRef, useState } from 'react';
import { formatCount, useStagger } from '../lib/chart';
import { cx } from '../lib/cx';
import { useControllable, useIsoLayoutEffect, useTween } from '../lib/hooks';
import { Seg } from '../lib/motion';
import '../designme.css';
import './bar-chart.css';

export interface BarChartSeries {
  /** Names the part in the hover readout and, when stacked, in the legend, like "Needed review" */
  label: string;
  /** How the hover readout names it, like "reviewed". Defaults to the label in lower case */
  tipLabel?: string;
  /** When stacked. Defaults to the chart palette: blue, purple, then orange */
  color?: string;
}

export interface BarChartBar {
  /** Under the bar, like "Mon" */
  label: string;
  /** One value per series, stacked from the bottom */
  values: number[];
}

export interface BarChartRange {
  key: string;
  /** On the switch, like "Week" */
  label: string;
  bars: BarChartBar[];
}

export interface BarChartProps {
  /** The name over the big number, like "Agent runs" */
  label: string;
  /** What each part of a bar means, in order. The hover readout breaks each bar down by these */
  series: BarChartSeries[];
  /** Draws each bar as a stack of its parts in the palette's colours, with a legend. Off by default: one bar in the
      accent, with the breakdown in the hover readout */
  stacked?: boolean;
  /** One set of bars per range. With more than one, a switch picks between them */
  ranges: BarChartRange[];
  /** Key of the range shown. Leave it out to let the switch change it */
  range?: string;
  /** Defaults to the first range */
  defaultRange?: string;
  onRangeChange?: (key: string) => void;
  /** What the values count, like "runs" in "66 runs" */
  unit?: string;
  /** Writes a value. Defaults to whole numbers like 1,240 */
  format?: (n: number) => string;
  className?: string;
}

// the colours of a stack's parts, in order
const PALETTE = ['var(--dm-c1)', 'var(--dm-c2)', 'var(--dm-c4)', 'var(--dm-c3)', 'var(--dm-c5)', 'var(--dm-c6)'];

/** Bars that grow in one after another, with a readout on hover that breaks each one down, and a switch between ranges. */
export function BarChart({ label, series, ranges, range, defaultRange, onRangeChange, unit, format = formatCount, stacked = false, className }: BarChartProps) {
  const [cur, setCur] = useControllable(range, defaultRange ?? ranges[0]?.key ?? '', onRangeChange);
  const count = Math.max(0, ...ranges.map(r => r.bars.length));
  // the bars draw a moment after the chart appears, then redraw left to right on every switch
  const at = useStagger(cur, count, 45, 200);
  const byKey = (k: string | null) => ranges.find(r => r.key === k);
  const shown = byKey(at[0]);
  const sum = (b?: BarChartBar) => b ? b.values.reduce((a, v) => a + v, 0) : 0;
  const total = useTween(shown ? shown.bars.reduce((a, b) => a + sum(b), 0) : 0, 900, 0);

  // the room the bars have, less the label under them
  const ch = useRef<HTMLDivElement>(null);
  const [room, setRoom] = useState(128);
  useIsoLayoutEffect(() => { if (ch.current) setRoom(ch.current.clientHeight - 22); }, []);
  const color = (j: number) => series[j]?.color ?? PALETTE[j % PALETTE.length];

  // a bar's readout sits beside it, level with its top: on its right while it fits there, then on its left, and always inside
  // the chart, over the bars and clear of the labels under them. It follows its bar while the bar grows or the range changes
  const cols = useRef<(HTMLDivElement | null)[]>([]);
  const [hot, setHot] = useState<number | null>(null);
  useEffect(() => {
    if (hot == null) return;
    let raf = 0;
    const place = () => {
      const b = cols.current[hot], c = ch.current, tt = b?.querySelector<HTMLElement>('.dm-bcx-tt'), st = b?.querySelector<HTMLElement>('.dm-bcx-st');
      if (b && c && tt && st) {
        const H = c.clientHeight, w = tt.offsetWidth, h = tt.offsetHeight, base = H - st.offsetTop - st.offsetHeight;
        tt.style.bottom = Math.max(base, Math.min(H - h, base + st.offsetHeight - h)) + 'px';
        tt.style.left = Math.max(-b.offsetLeft, Math.min(c.clientWidth - b.offsetLeft - w, b.offsetLeft + b.offsetWidth + 6 + w <= c.clientWidth ? b.offsetWidth + 6 : -w - 6)) + 'px';
      }
      raf = requestAnimationFrame(place);
    };
    place();
    return () => cancelAnimationFrame(raf);
  }, [hot]);

  return (
    <div data-dm="" className={cx('dm-bcx dm-panel', className)}>
      <div className="dm-bcx-h">
        <div><span className="dm-muted">{label}</span><b className="dm-num dm-bcx-v">{format(total)}</b></div>
        {ranges.length > 1 && (
          <Seg className="dm-bcx-rg" label="Range" value={cur} onChange={setCur} options={ranges.map(r => ({ value: r.key, label: r.label }))} />
        )}
      </div>
      <div className="dm-bcx-ch" ref={ch}>
        {Array.from({ length: count }, (_, i) => {
          const r = byKey(at[i]), bar = r?.bars[i], top = r ? Math.max(...r.bars.map(sum)) * 1.08 : 1;
          const tip = shown?.bars[i];
          return (
            <div key={i} className="dm-bcx-b" ref={el => { cols.current[i] = el; }} onPointerEnter={() => setHot(i)} onPointerLeave={() => setHot(h => h === i ? null : h)}>
              <div className="dm-bcx-tt">
                <b className="dm-num">{tip && `${format(sum(tip))}${unit ? ' ' + unit : ''}`}</b>
                {/* each part on a line of its own, so the readout stays narrow enough to sit beside its bar */}
                {tip && tip.values.map((v, j) => <span key={j} className="dm-num">{`${format(v)} ${series[j]?.tipLabel ?? series[j]?.label.toLowerCase() ?? ''}`}</span>)}
              </div>
              <div className="dm-bcx-st">
                {stacked ? series.map((_, j) => {
                  const v = bar?.values[j] ?? 0;
                  return <i key={j} style={{ height: bar ? Math.max(v ? 3 : 0, v / top * room) : 0, background: color(j) }} />;
                }) : <i style={{ height: bar ? Math.max(sum(bar) ? 3 : 0, sum(bar) / top * room) : 0 }} />}
              </div>
              <div className="dm-bcx-l">{tip?.label}</div>
            </div>
          );
        })}
      </div>
      {stacked && <div className="dm-bcx-lg dm-muted">{series.map((s, j) => <span key={j}><i style={{ background: color(j) }} />{s.label}</span>)}</div>}
    </div>
  );
}

/* Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync. */
/* ---------- Bar chart ---------- */
/* agent runs a day: one bar each in the accent, with no legend, and each bar's breakdown in its hover readout. The readout
   is the page's tooltip (opaque and neutral) beside the bar it reads, level with its top, on the side with room and always
   inside the chart (the script places it, and it follows the bar as it grows). The content sits 16px in from every edge */
.dm-bcx{padding:var(--dm-s-4);display:flex;flex-direction:column;gap:var(--dm-s-3)}
.dm-bcx-h{display:flex;justify-content:space-between;align-items:flex-start;gap:10px}
.dm-bcx-h>div:first-child{display:flex;flex-direction:column;font-size:12.5px;line-height:18px}
.dm-bcx-v{font-size:14px;line-height:20px;font-weight:500;letter-spacing:-.02em}
.dm-bcx-rg button{font-size:12px;height:26px;padding:0 10px}
.dm-bcx-ch{display:flex;align-items:flex-end;gap:var(--dm-s-2);height:150px;position:relative}
.dm-bcx-b{flex:1;height:100%;display:flex;flex-direction:column;justify-content:flex-end;align-items:stretch;gap:0;position:relative;cursor:default}
.dm-bcx-st{display:flex;flex-direction:column-reverse;gap:2px;border-radius:calc(7px * var(--dm-rk-m,var(--dm-rk)));overflow:hidden;transition:opacity var(--dm-t-fast) var(--dm-ease)}
.dm-bcx-st i{display:block;height:0;transition:height .7s var(--dm-ease)}
.dm-bcx-st i:nth-child(1){background:var(--dm-c1)}
@media (hover:hover) and (pointer:fine){.dm-bcx-ch:hover .dm-bcx-b:not(:hover) .dm-bcx-st{opacity:.4}}
.dm-bcx-l{font-size:11px;line-height:14px;color:var(--dm-muted);text-align:center;margin-top:6px;height:14px}
.dm-bcx-tt{position:absolute;left:0;bottom:calc(100% + 6px);z-index:2;padding:6px 9px;border-radius:var(--dm-r-sm);background:var(--dm-tip-bg,var(--dm-ink));color:var(--dm-tip-fg,var(--dm-on-ink));box-shadow:var(--dm-tip-ring,none);font-size:12px;line-height:1.35;white-space:nowrap;opacity:0;pointer-events:none;transform:translateY(4px);transition:opacity var(--dm-t-fast) var(--dm-ease),transform var(--dm-t) var(--dm-ease);display:flex;flex-direction:column}
.dm-bcx-tt b{font-weight:500}
.dm-bcx-tt span{color:color-mix(in srgb,var(--dm-tip-fg,var(--dm-on-ink)) 76%,var(--dm-tip-bg,var(--dm-ink)))}
@media (hover:hover) and (pointer:fine){.dm-bcx-b:hover .dm-bcx-tt{opacity:1;transform:none}}
.dm-bcx-lg{display:flex;gap:14px;font-size:12px;flex-wrap:wrap}
.dm-bcx-lg span{display:flex;align-items:center;gap:6px}
.dm-bcx-lg i{width:8px;height:8px;border-radius:var(--dm-r-tiny,3px)}
/* Clean: the bars stand on a hairline baseline (half strength) with their tops rounded, as a bar chart is usually drawn */
:root[data-style="clean"] .dm-bcx-st,:root [data-style="clean"] .dm-bcx-st,:root [data-style="clean"].dm-bcx-st{border-radius:calc(6px * var(--dm-rk-m,var(--dm-rk))) calc(6px * var(--dm-rk-m,var(--dm-rk))) 2px 2px}
:root[data-style="clean"] .dm-bcx-ch,:root [data-style="clean"] .dm-bcx-ch,:root [data-style="clean"].dm-bcx-ch{background:linear-gradient(color-mix(in srgb,var(--dm-line) 50%,transparent),color-mix(in srgb,var(--dm-line) 50%,transparent)) left 0 bottom 20px/100% 1px no-repeat}

